import{_ as e,c as p,o as r,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"48、【井】 巽下坎上","description":"周易尚氏学 - 48、【井】 巽下坎上","frontmatter":{"title":"48、【井】 巽下坎上","description":"周易尚氏学 - 48、【井】 巽下坎上"},"headers":[],"relativePath":"zh/classics/shangshi/053.md","filePath":"zh/classics/shangshi/053.md"}'),h={name:"zh/classics/shangshi/053.md"};function s(t,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_48、【井】-巽下坎上" tabindex="-1">48、【井】 巽下坎上 <a class="header-anchor" href="#_48、【井】-巽下坎上" aria-label="Permalink to “48、【井】 巽下坎上”">​</a></h1><p>水在泽下 泽竭故困。水在泽中。汲之不穷。故兑为并。易林复之旅云。井沸釜鸣。以旅互兑为井。郑玄以巽木为桔槔。汲水以取并象。格槔焉有在井下者乎。兑为井。坤为邑。泰初往坤中。故改邑。二至四仍兑。与泰体同。故不改井。不改故无丧得。初至四正反兑。故曰往来井井。易林益之萃云。往来井井。即以苹三至上正反兑。为往来井井。荀云。讫竟也。讫至者。言更（左丝）系至并底而尽也。繘绠也。亦未繘者。言巽绳在下。尚未繘瓶使上也。其以讫为几。渭瓶几至井口而覆者非也。经明曰未繘。若至井口。则已繘矣。中爻离为瓶。正当毁折之地。而巽为绳。故曰羸。羸累通。井羸其瓶者。言瓶为井甃所拘羸钩挂也。瓶既为井所挂碍。非覆即破。故凶。扬子云酒箴云。子犹瓶矣。居井之湄。不得左右。牵于缠征。一旦f？ 碍。为裳所车（右3田）。注f？县也。g？并以砖为甃也。车（右3田）系也。言瓶县为井砖所挂碍。而瓶受系也。是扬子读并羸其瓶。井不属上读。后荀爽袭子云。亦以井属下读。其以繘井为名者。则下文之羸其瓶。莫详其故矣。非也。赢易林家人之颐云。长股赢户。长股即箫（左虫）蛸。赢户者。言以比丝缠绕于户上也。是以赢为累。故荀训为拘赢。虞释为钧赢。他若陆绩蜀才作累。王肃作缥。王肃作缧。其字虽异。其音皆同。其义如一。</p><p>彖曰。巽乎水而上水。井。井养而不穷也。改己不改井。乃以刚中也。讫王亦未繘。来有功也。井羸其瓶。是以凶也。</p><p>句依荀读。故汲古阁所刊李氏集解。及雅丽堂刊本。皆井字属下。坎在上故曰上水。巽人也。巽乎水而上水。言以瓶人水。汲水使上也。水所以养人。取之不竭。故养而不穷。二五皆刚。故不改。未繘故无功。井拘累其瓶使水覆。故凶。讫至亦未箫（左虫）。荀注云汽竟也。繘所以出水通井。今居初未得应五。故未繘也。不与井连文。井羸其瓶。荀注云。井谓二。瓶谓初。初欲应五。为二所拘羸。以井属下读。与扬子同。故从之。</p><p>象曰。木上有水。井。君子以劳民劝相。</p><p>坎为众为民为劳卦。故曰劳民。释诂相导也。兑为言。故曰劝相。言以言语劝导。使有所勉也。</p><p>初六。井泥不食。旧井无禽。</p><p>初在井下。故曰泥。兑口为食。兑覆故不食。并原以汲水。今无水而泥。其为旧井无疑也。禽获也。无水故无所得。其以禽鸟为诂者非。又按旧井者废井也。兑为井。兑覆为巽。故井废。</p><h3 id="象曰。井泥不食。下也。旧井无禽。时舍也。" tabindex="-1">象曰。井泥不食。下也。旧井无禽。时舍也。 <a class="header-anchor" href="#象曰。井泥不食。下也。旧井无禽。时舍也。" aria-label="Permalink to “象曰。井泥不食。下也。旧井无禽。时舍也。”">​</a></h3><p>舍。弃也。</p><p>九二。井谷射鲋，瓮敝漏。</p><p>二后兑体之下。故曰并谷。巽为鱼。故曰鲋。子夏传虾h？ 也。伏震为射。虾g？穴居水际。故曰并谷射鲋。伏震为雍（下瓦）。巽下缺。雍（下瓦）无当。故敝漏。夫井内之穴。井矢所能加。雍（下瓦）漏则水泄。而失其用。以二前遇阳。应亦阳。故动静皆不适也。</p><h3 id="象曰。井谷射鲋-无与也。" tabindex="-1">象曰。井谷射鲋，无与也。 <a class="header-anchor" href="#象曰。井谷射鲋-无与也。" aria-label="Permalink to “象曰。井谷射鲋，无与也。”">​</a></h3><p>言五元应与。</p><p>九三。井渫不食，为我心恻。可用汲，王明，并受其福。</p><p>三应在上。上居坎水上。故曰井渫。汉书王莽传。溃（左示）毛（左目）不渫。注渫彻也。通出。扬子方言。渫歇也。兹曰井渫。谓井水浑蜀沉歇而清彻也。初为促则上为渫。正上居坎水上之象也。夫水洁（左无）宜食矣。乃竟不食者。以五亦阳为阻三不得应上也。兑为食。为使也。坎为心为忧。为我心恻者。言三被阻。不能汲上。使我心优也。然三与上究为正应。上水既渫而清。三仅可汲。五岂能终阻之。王谓五。五坎为隐伏。故不明。然王终有明时。王明则三上汲引。养而不穷。天下普受其福矣。凡爻有正应者。初虽有阻。终必相合。同人九五曰。先号眺（左口）而后笑。大师克相遇。言五克去三四之阻。终能遇二也。渐九五曰。终莫之胜吉。得所愿也。盲五终能胜三。与二相合也。兹害三者五。五君位尊。三不敢言克言胜。只冀王明而已。王明则三上终相遇也。文王服事忠诚。情见乎辞。因五为阻。故呼王明。旧解不知不食之故。在五敌为阻。又不知王明并受其福。即言三上终能应与。特以五而变其辞耳。故无一得解者。</p><h3 id="象曰。井渫不食-行恻也。求王明-受福也。" tabindex="-1">象曰。井渫不食，行恻也。求王明，受福也。 <a class="header-anchor" href="#象曰。井渫不食-行恻也。求王明-受福也。" aria-label="Permalink to “象曰。井渫不食，行恻也。求王明，受福也。”">​</a></h3><p>不食之故，其咎在五。故曰求王明。</p><p>六四。井甃,无咎。</p><p>以瓦甓砌井曰甃。兑为井。六四居兑上。则井将修成。故无咎。</p><h3 id="象日。井甃无咎。修井也。" tabindex="-1">象日。井甃无咎。修井也。 <a class="header-anchor" href="#象日。井甃无咎。修井也。" aria-label="Permalink to “象日。井甃无咎。修井也。”">​</a></h3><p>甃修也。</p><p>九五。井冽，寒泉食。</p><p>冽甘也。坎为寒为泉。泉既甘冽。故可食。</p><h3 id="象曰。寒泉之食。中正也。" tabindex="-1">象曰。寒泉之食。中正也。 <a class="header-anchor" href="#象曰。寒泉之食。中正也。" aria-label="Permalink to “象曰。寒泉之食。中正也。”">​</a></h3><p>五虽无应。然位正中。故可食</p><p>上六、井收勿幕。有孚元吉。</p><p>收成也。幕盖也。覆也。坎为隐伏。故为盖覆。六居坎上故勿幕。言井既成。以出水为功。不宜盖覆也。 三得阳应。故有孚而吉。</p><h3 id="象曰。元吉在上。大成也。" tabindex="-1">象曰。元吉在上。大成也。 <a class="header-anchor" href="#象曰。元吉在上。大成也。" aria-label="Permalink to “象曰。元吉在上。大成也。”">​</a></h3><p>成即收也。</p>',30)])])}const f=e(h,[["render",s]]);export{_ as __pageData,f as default};
